package com.alfahdtv.app;
import android.app.Activity;import android.app.PictureInPictureParams;import android.os.Build;import android.os.Bundle;import android.util.Rational;import android.view.View;import android.view.WindowManager;import androidx.media3.common.MediaItem;import androidx.media3.exoplayer.ExoPlayer;import androidx.media3.ui.PlayerView;
public final class PlayerActivity extends Activity{private ExoPlayer player;private PlayerView view;private String url;@Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);url=getIntent().getStringExtra("media_url");view=new PlayerView(this);view.setUseController(true);setContentView(view);}@Override protected void onStart(){super.onStart();if(player==null)prepare();}private void prepare(){if(url==null||!url.startsWith("https://")){finish();return;}player=new ExoPlayer.Builder(this).build();view.setPlayer(player);player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();}@Override public void onUserLeaveHint(){if(Build.VERSION.SDK_INT>=26)enterPictureInPictureMode(new PictureInPictureParams.Builder().setAspectRatio(new Rational(16,9)).build());super.onUserLeaveHint();}@Override protected void onStop(){if(player!=null){player.release();player=null;}super.onStop();}}
